//! The controller file that maps the devices of player assignments.
//!
//! MAME takes one controller file (`-ctrlr <name>`, `<name>.cfg` in
//! `-ctrlrpath`). The generated file starts with a `<system name="default">`
//! section holding one `<mapdevice device="<id>" controller="JOYCODE_<n>"/>`
//! per mapped player, followed by every section of the baseline file (the
//! profile's `base.cfg` or the native controller file), copied verbatim:
//! the section is inserted right after `<mameconfig>`, so nothing of the
//! baseline is reinterpreted, moved or dropped (verified with MAME 0.289).
//!
//! MAME applies the sections in file order and each `mapdevice` swaps two
//! device indexes, so mappings of the baseline that touch the same devices
//! or joystick indexes would undo or reorder the generated ones. Policy:
//!
//! - a baseline mapping identical to a generated one (same device id
//!   without case, same controller) is compatible and kept;
//! - a baseline mapping of another class (`GUNCODE_n`...) or of a joystick
//!   index nobody is assigned to, for a device id unrelated to every mapped
//!   one, is kept;
//! - any other baseline mapping is a conflict: the composition fails with a
//!   message naming it. The baseline is never edited.
//!
//! The file name derives from the content (`ymdb-<FNV-1a 64 hex>`), so equal
//! inputs give the same file and a file is never reused for other content.

use std::fmt::Write as _;

use quick_xml::escape::escape;

use super::base_file::{self, ControllerSlot};
use super::model::device_ids_overlap;

/// Prefix of generated controller file names.
pub const FILE_PREFIX: &str = "ymdb-";

/// A device to move to the joystick index of a player.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PlayerDevice {
    /// 1-based player number, also the MAME joystick index.
    pub player: u32,
    pub device_id: String,
}

/// A baseline whose sections are kept.
#[derive(Debug, Clone, Copy)]
pub struct Baseline<'a> {
    /// How messages name the file.
    pub label: &'a str,
    pub content: &'a [u8],
}

/// A composed controller file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ControllerFile {
    /// The `-ctrlr` value: the file name without `.cfg`.
    pub name: String,
    /// 16 hexadecimal digits identifying the content.
    pub hash: String,
    pub content: String,
}

impl ControllerFile {
    pub fn file_name(&self) -> String {
        format!("{}.cfg", self.name)
    }
}

/// Composes the controller file of `devices` (at least one, valid ids, one
/// per player and per device) and `baseline`.
pub fn compose(
    devices: &[PlayerDevice],
    baseline: Option<Baseline<'_>>,
) -> Result<ControllerFile, String> {
    let section = mapping_section(devices)?;
    let content = match baseline {
        None => format!(
            "<?xml version=\"1.0\"?>\n<mameconfig version=\"{}\">{section}\n</mameconfig>\n",
            base_file::SUPPORTED_VERSION
        ),
        Some(baseline) => {
            let text = std::str::from_utf8(baseline.content)
                .map_err(|_| format!("{} is not a UTF-8 text file", baseline.label))?;
            let info = base_file::analyze(baseline.content)
                .map_err(|error| format!("{} cannot be used: {error}", baseline.label))?;
            check_conflicts(devices, &info.mappings, baseline.label)?;
            let (head, tail) = text.split_at(info.root_content_start);
            format!("{head}{section}{tail}")
        }
    };
    let hash = format!("{:016x}", fnv1a(content.as_bytes()));
    Ok(ControllerFile {
        name: format!("{FILE_PREFIX}{hash}"),
        hash,
        content,
    })
}

fn mapping_section(devices: &[PlayerDevice]) -> Result<String, String> {
    if devices.is_empty() {
        return Err("no device to map".to_owned());
    }
    let mut section = String::from(
        "\n    <!-- Generated by YMDB: device mappings of the player assignments. -->\n    <system name=\"default\">\n        <input>\n",
    );
    for (index, device) in devices.iter().enumerate() {
        let id = device.device_id.as_str();
        if id.trim().is_empty() || id.chars().any(char::is_control) {
            return Err(format!("invalid device id for player {}", device.player));
        }
        if !(1..=u32::try_from(super::model::MAX_PLAYERS).unwrap_or(u32::MAX))
            .contains(&device.player)
        {
            return Err(format!("invalid player number {}", device.player));
        }
        for other in &devices[..index] {
            if other.player == device.player {
                return Err(format!("player {} is mapped twice", device.player));
            }
            if device_ids_overlap(&other.device_id, id) {
                return Err(format!(
                    "players {} and {} are mapped to the same device ('{}')",
                    other.player, device.player, other.device_id
                ));
            }
        }
        let _ = writeln!(
            section,
            "            <mapdevice device=\"{}\" controller=\"{}\" />",
            escape(id),
            ControllerSlot::joystick(device.player)
        );
    }
    section.push_str("        </input>\n    </system>");
    Ok(section)
}

fn check_conflicts(
    devices: &[PlayerDevice],
    mappings: &[base_file::DeviceMapping],
    label: &str,
) -> Result<(), String> {
    for mapping in mappings {
        let slot = mapping.controller;
        let same_slot = devices
            .iter()
            .find(|device| ControllerSlot::joystick(device.player) == slot);
        let same_device = devices
            .iter()
            .find(|device| device_ids_overlap(&device.device_id, &mapping.device));
        let identical = same_slot.is_some_and(|device| {
            device.device_id.eq_ignore_ascii_case(&mapping.device) && same_device == Some(device)
        });
        if identical {
            continue;
        }
        if let Some(device) = same_slot {
            return Err(format!(
                "{label} already maps the device '{}' to {slot} (section '{}'), the joystick of player {}: remove that mapping from it or assign player {} no controller",
                mapping.device, mapping.system, device.player, device.player
            ));
        }
        if let Some(device) = same_device {
            return Err(format!(
                "{label} maps the device '{}' to {slot} (section '{}'), but player {} is assigned that device: remove that mapping from it",
                mapping.device, mapping.system, device.player
            ));
        }
    }
    Ok(())
}

/// 64-bit FNV-1a: a small, stable content hash for file names.
fn fnv1a(bytes: &[u8]) -> u64 {
    const OFFSET: u64 = 0xcbf2_9ce4_8422_2325;
    const PRIME: u64 = 0x0000_0100_0000_01b3;
    bytes.iter().fold(OFFSET, |hash, byte| {
        (hash ^ u64::from(*byte)).wrapping_mul(PRIME)
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    const GP100_A: &str = "USB gamepad            product_e401081f-0000-0000-0000-504944564944 instance_1a2b3c4d-1111-11f0-8001-444553540000";
    const GP100_B: &str = "USB gamepad            product_e401081f-0000-0000-0000-504944564944 instance_5e6f7a8b-2222-11f1-8001-444553540000";

    fn device(player: u32, id: &str) -> PlayerDevice {
        PlayerDevice {
            player,
            device_id: id.to_owned(),
        }
    }

    const BASE: &str = r#"<?xml version="1.0"?>
<!-- My arcade panel -->
<mameconfig version="10">
    <system name="sf2">
        <input>
            <port type="P1_BUTTON1"><newseq type="standard">JOYCODE_1_BUTTON3</newseq></port>
        </input>
    </system>
    <system name="default">
        <input>
            <port type="UI_CONFIGURE"><newseq type="standard">KEYCODE_TAB</newseq></port>
            <mapdevice device="HID Lightgun" controller="GUNCODE_1" />
        </input>
    </system>
</mameconfig>
"#;

    #[test]
    fn composes_a_file_without_baseline() {
        let file =
            compose(&[device(1, GP100_B), device(2, "XInput Player 1")], None).expect("compose");
        let info = base_file::validate(file.content.as_bytes()).expect("valid MAME file");
        assert_eq!(info.systems, ["default"]);
        assert_eq!(
            info.mappings
                .iter()
                .map(|mapping| (mapping.device.as_str(), mapping.controller.to_string()))
                .collect::<Vec<_>>(),
            [
                (GP100_B, "JOYCODE_1".to_owned()),
                ("XInput Player 1", "JOYCODE_2".to_owned())
            ]
        );
        assert_eq!(file.name, format!("ymdb-{}", file.hash));
        assert_eq!(file.hash.len(), 16);
        assert_eq!(file.file_name(), format!("{}.cfg", file.name));
    }

    #[test]
    fn keeps_every_section_of_the_baseline_verbatim() {
        let file = compose(
            &[device(1, "XInput Player 1"), device(3, GP100_A)],
            Some(Baseline {
                label: "the controller file of 'Arcade'",
                content: BASE.as_bytes(),
            }),
        )
        .expect("compose");
        // The generated section comes first, then the baseline as it was.
        let start = BASE.find("<mameconfig version=\"10\">").expect("root")
            + "<mameconfig version=\"10\">".len();
        assert!(file.content.starts_with(&BASE[..start]));
        assert!(file.content.ends_with(&BASE[start..]));
        let info = base_file::validate(file.content.as_bytes()).expect("valid");
        assert_eq!(info.systems, ["default", "sf2", "default"]);
        assert_eq!(info.mappings.len(), 3);
        assert_eq!(info.mappings[1].controller.to_string(), "JOYCODE_3");
    }

    #[test]
    fn the_name_derives_from_the_content() {
        let a = compose(&[device(1, GP100_A)], None).expect("a");
        let again = compose(&[device(1, GP100_A)], None).expect("again");
        assert_eq!(a, again);
        let other_player = compose(&[device(2, GP100_A)], None).expect("b");
        let other_device = compose(&[device(1, GP100_B)], None).expect("c");
        let with_base = compose(
            &[device(1, GP100_A)],
            Some(Baseline {
                label: "base",
                content: BASE.as_bytes(),
            }),
        )
        .expect("d");
        let names = [&a, &other_player, &other_device, &with_base].map(|file| file.name.clone());
        for (index, name) in names.iter().enumerate() {
            assert!(!names[index + 1..].contains(name), "{name}");
        }
        // Stable across runs and platforms (FNV-1a 64 of the exact bytes).
        assert_eq!(format!("{:016x}", fnv1a(b"")), "cbf29ce484222325");
        assert_eq!(format!("{:016x}", fnv1a(b"a")), "af63dc4c8601ec8c");
    }

    #[test]
    fn escapes_device_ids() {
        let id = r#"Pad "Pro" <X> & 'Co'"#;
        let file = compose(&[device(1, id)], None).expect("compose");
        assert!(!file.content.contains("<X>"));
        let info = base_file::validate(file.content.as_bytes()).expect("valid");
        assert_eq!(info.mappings[0].device, id);
        // Control characters cannot be expressed in an attribute.
        assert!(compose(&[device(1, "pad\nx")], None).is_err());
        assert!(compose(&[device(1, " ")], None).is_err());
    }

    #[test]
    fn refuses_contradictory_mappings() {
        assert!(compose(&[], None).unwrap_err().contains("no device"));
        assert!(
            compose(&[device(1, GP100_A), device(1, GP100_B)], None)
                .unwrap_err()
                .contains("mapped twice")
        );
        assert!(
            compose(
                &[device(1, GP100_A), device(2, &GP100_A.to_lowercase())],
                None
            )
            .unwrap_err()
            .contains("same device")
        );
        // MAME matches substrings: a prefix would catch the other device.
        assert!(
            compose(&[device(1, "USB gamepad"), device(2, GP100_B)], None)
                .unwrap_err()
                .contains("same device")
        );
        assert!(compose(&[device(0, GP100_A)], None).is_err());
        assert!(compose(&[device(11, GP100_A)], None).is_err());
    }

    fn base_with(mapping: &str) -> String {
        format!(
            r#"<mameconfig version="10"><system name="default"><input>{mapping}</input></system><system name="neogeo"><input/></system></mameconfig>"#
        )
    }

    #[test]
    fn applies_the_policy_for_mappings_of_the_baseline() {
        let compose_with = |mapping: &str| {
            let base = base_with(mapping);
            compose(
                &[device(1, GP100_A), device(2, "XInput Player 1")],
                Some(Baseline {
                    label: "the controller file of 'Arcade'",
                    content: base.as_bytes(),
                }),
            )
        };
        // Identical mapping (case differs): kept, no conflict.
        let file = compose_with(&format!(
            r#"<mapdevice device="{}" controller="JOYCODE_1"/>"#,
            GP100_A.to_uppercase()
        ))
        .expect("identical");
        assert_eq!(
            base_file::analyze(file.content.as_bytes())
                .expect("ok")
                .mappings
                .len(),
            3
        );
        // Other classes and unrelated joysticks on free indexes: kept.
        compose_with(r#"<mapdevice device="HID Lightgun" controller="GUNCODE_1"/>"#).expect("gun");
        compose_with(r#"<mapdevice device="Arcade stick" controller="JOYCODE_3"/>"#).expect("free");
        // Another device on an assigned index.
        let error = compose_with(r#"<mapdevice device="Arcade stick" controller="JOYCODE_2"/>"#)
            .unwrap_err();
        assert!(
            error.contains("JOYCODE_2") && error.contains("player 2"),
            "{error}"
        );
        // An assigned device moved elsewhere, even in a machine section.
        let base = r#"<mameconfig version="10"><system name="default"><input/></system><system name="neogeo"><input><mapdevice device="XInput Player 1" controller="JOYCODE_4"/></input></system></mameconfig>"#;
        let error = compose(
            &[device(2, "XInput Player 1")],
            Some(Baseline {
                label: "base",
                content: base.as_bytes(),
            }),
        )
        .unwrap_err();
        assert!(
            error.contains("neogeo") && error.contains("player 2"),
            "{error}"
        );
        // A substring of an assigned device id.
        let error = compose_with(r#"<mapdevice device="usb GAMEPAD" controller="JOYCODE_5"/>"#)
            .unwrap_err();
        assert!(error.contains("player 1"), "{error}");
    }

    #[test]
    fn reports_unusable_baselines() {
        for (content, expected) in [
            (&b"<mameconfig version=\"10\"><system name=\"default\"><input>"[..], "ends before"),
            (&b"\xff\xfe<mameconfig/>"[..], "UTF-8"),
            (
                &br#"<mameconfig version="10"><system name="default"><input><mapdevice device="x" controller="JOY_1"/></input></system></mameconfig>"#[..],
                "invalid controller",
            ),
        ] {
            let error = compose(
                &[device(1, GP100_A)],
                Some(Baseline {
                    label: "the native controller file 'xarcade'",
                    content,
                }),
            )
            .unwrap_err();
            assert!(error.contains(expected), "{error}");
            assert!(error.contains("xarcade"), "{error}");
        }
        // A baseline without a default section is accepted: the generated
        // section makes MAME load the file for every machine.
        let base = r#"<mameconfig version="10"><system name="sf2"><input/></system></mameconfig>"#;
        compose(
            &[device(1, GP100_A)],
            Some(Baseline {
                label: "base",
                content: base.as_bytes(),
            }),
        )
        .expect("machine sections only");
    }
}
